const btn=(s,c='')=>`<button class="${c}">${s}</button>`;
const pill=(s,c='')=>`<span class="pill ${c}">${s}</span>`;
const field=(l,v,h='')=>`<div class="field"><div class="label">${l}</div><div class="input">${v}</div>${h?`<div class="source-hint">${h}</div>`:''}</div>`;
const box=(t,c,cl='')=>`<div class="box ${cl}">${t?`<h3>${t}</h3>`:''}${c}</div>`;
const note=(s,c='')=>`<div class="note ${c}">${s}</div>`;
const table=(headers,rows,selected=-1,cl='')=>`<div class="table ${cl}"><table><thead><tr>${headers.map(h=>`<th>${h}</th>`).join('')}</tr></thead><tbody>${rows.map((r,i)=>`<tr class="${i===selected?'selected':''}">${r.map((v,j)=>`<td${j===0?' class="key"':''}>${v}</td>`).join('')}</tr>`).join('')}</tbody></table></div>`;
const map=(a,b)=>`<div class="mapping"><div class="input">${a}</div><span>→</span><div class="input">${b}</div></div>`;
const brand=`<div class="logo"><span class="brand"><i></i><i></i><i></i></span><span>Noa<em>CG</em></span></div>`;
function nav(mode='production',title='Harbour Cup',live=false){return `<div class="nav">${brand}${btn('← Back','small')}${mode==='wizard'?`<b>Import graphic</b><span class="muted">· ${title}</span>`:`<b>${title}</b>${pill(live?'PUBLISHED':'LOCAL',live?'green':'')}`}<span class="spacer"></span>${mode==='wizard'?`<span class="mono muted">AUTHORING</span>${btn('Home','small')}`:`<div class="tabs"><span class="tab active">Playout</span><span class="tab">Data</span><span class="tab">Messages</span></div>${btn('Setup ▾','small')}${btn(live?'Published ✓':'Publish','small')}${btn('■ All out','small danger')}`}</div>`}
function steps(active=2){return `<div class="steps">${['Start','Design','Fields','Animation','Finish'].map((s,i)=>`<div class="step ${i===active?'active':i<active?'done':''}"><span class="num">${i<active?'✓':i+1}</span><span>${s}<small>${['Choose mode','Your artwork','Operator fields','In & out motion','Name & save'][i]}</small></span></div>`).join('')}<div class="line"></div><div class="eyebrow">PROJECT FORMAT</div><p style="font-size:12px">16:9 · 1920 × 1080<br>25 fps</p></div>`}
function scoreGraphic(sel=false,score='3',ticker=false){return `<div class="graphic"><div class="strap-top">HARBOUR CUP / QUARTER-FINAL</div><div class="match-strip"><div class="team"><span class="crest">N</span>NORTH</div><div class="score"><span class="${sel?'sel':''}">${score}</span><small>:</small>2</div><div class="team" style="justify-content:flex-end">ORBIT<span class="crest away">O</span></div></div>${ticker?`<div class="ticker">NEXT · LYNX vs REEF at 20:30　 /　 HALO vs KITE at 21:00</div>`:''}</div>`}
function scoreCanvas(sel=false,score='3',cl=''){return `<div class="canvas ${cl}"><div class="safe"></div>${scoreGraphic(sel,score)}</div>`}
const teams=['North','Orbit','Lynx','Reef','Halo','Kite','Volt','Echo','Nova','Wave','Iris','Bolt','Axis','Dune','Flux','Pine'];
function bracket(){const round=(names,title)=>`<div class="round" data-round="${title}">${Array.from({length:names.length/2},(_,i)=>`<div class="match"><div class="${i===0&&title==='ROUND OF 16'?'win':''}"><span><i class="mini-crest">${names[i*2][0]}</i>${names[i*2]}</span><b>${title==='ROUND OF 16'?(i===0?3:0):'–'}</b></div><div><span><i class="mini-crest">${names[i*2+1][0]}</i>${names[i*2+1]}</span><b>${title==='ROUND OF 16'?(i===0?2:0):'–'}</b></div></div>`).join('')}</div>`;return `<div class="bracket"><div class="bracket-head">HARBOUR CUP <small>TOP 16 / PLAYOFFS</small></div><div class="rounds">${round(teams,'ROUND OF 16')}${round(['Winner R1','Winner R2','Winner R3','Winner R4','Winner R5','Winner R6','Winner R7','Winner R8'],'QUARTER-FINALS')}${round(['Winner Q1','Winner Q2','Winner Q3','Winner Q4'],'SEMI-FINALS')}<div class="round" data-round="FINAL"><div class="match final"><div>Winner S1 <b>–</b></div><div>Winner S2 <b>–</b></div><div class="trophy">◇</div></div></div></div></div>`}
function ad(){return `<div class="commercial"><div class="adcopy"><div class="adbrand">NORTH / EQUIPMENT</div><h3>Built for<br>the long run.</h3><p>Official hydration partner</p><div class="adline"></div></div><div class="adtag">HARBOUR CUP　·　PARTNER FEATURE 01 / 03</div></div>`}
function player(score='12'){return `<div class="player"><div class="video-note">PLAYER VIDEO · ILLUSTRATIVE BACKGROUND</div><div class="head"></div><div class="body"></div><div class="graphic"><div class="player-name"><div class="avatar">AK</div><div class="nameblock"><strong>Ari Kova</strong><small>NORTH / PLAYER 07</small></div><span class="status">READY</span><div class="player-score">${score}</div></div><div class="scroll">LAST ROUND　+3　 /　 BEST STREAK　7</div></div></div>`}
const canvas=(art,cl='')=>`<div class="canvas ${cl}">${art}</div>`;
function wizard(settings,preview,active=2){return `<div class="workspace wizard">${steps(active)}<div class="settings">${settings}</div><div class="preview-area">${preview}</div></div>`}
const preview=(art,caption='Imported artwork',cl='large')=>`<div class="preview-label"><span>PREVIEW · ${caption}</span>${pill('1920 × 1080')}</div>${canvas(art,cl)}<div class="under"><span>SAFE AREA 7%</span><span>25 FPS　·　100%</span></div>`;
function rundown(kind='svg',live=false){const names=kind==='bracket'?['Top 16 overview','Quarter-final focus','Match scorebug']:kind==='ad'?['North partner roll','Hosted partner bumper','Back to studio']:kind==='player'?['Ari · player overlay','North scorebug','Match intro']:['Quarter-final · North / Orbit','Final · North / Orbit','Opening title'];return `<aside class="rundown"><div class="row spread"><h3>Cue rundown</h3>${btn('+','small')}</div>${names.map((n,i)=>`<div class="cue ${i===0?(live?'live':'active'):''}"><span class="muted">${i+1}</span><div><b>${n}</b><small>${i===0?(live?'● ON AIR':'● IN PREVIEW'):'Ready'}　·　L${20+i}</small></div></div>`).join('')}<div class="bottomspace">${note('Connections belong to the graphic. Every cue of that graphic follows.')}</div><div style="margin-top:24px">${btn('+ Add a graphic…','widebutton')}</div></aside>`}
function prod(art,editor,{kind='svg',live=false,sources='',title='Harbour Cup',program=null}={}){return nav('production',title,live)+`<div class="workspace production"><main>${sources}<div class="monitors"><div><div class="preview-label"><span class="amber">● PREVIEW</span><span>Selected cue</span></div>${canvas(art,'preview')}</div><div><div class="preview-label"><span class="red">● PROGRAM</span><span>${live?'ON AIR · L20':'OFF AIR'}</span></div>${canvas(live?(program||art):'<div class="empty">No graphic on air</div>','program')}</div><div class="transport">${btn(live?'■ Take off':'▶ Take','primary')}${btn('↻ Re-take')}${btn('✎ Update')}${btn('› Next','ghost')}${btn('■ Out','ghost')}</div></div>${editor}</main>${rundown(kind,live)}</div>`}
const source=(label,status='Checked 3 s ago',pause='Pause',warning=false)=>`<div class="sources"><span class="${warning?'red':'green'}">●</span><b>${label}</b><span class="muted">${status}</span><span class="spacer"></span>${pause==='Details'?'':btn(pause,'small')}${btn('Details','small ghost')}</div>`;
const slides=[];
function add(id,title,subtitle,body,click,next,verify){slides.push({id,title,html:`<section class="slide" id="${id}" data-title="${title}"><header class="review-head"><div><h1>${title}</h1><p>${subtitle}</p></div><div class="research">PROPOSED UI · STATIC MOCKUP<br>SIMULATED DATA · NO PRODUCT CHANGES</div></header><div class="app">${body}</div><footer class="foot"><div><b>CLICK</b>${click}</div><div><b>WHAT HAPPENS NEXT</b>${next}</div><div><b>VERIFY</b>${verify}</div></footer></section>`})}

add('01-svg-import','01 / SVG · Start with unfamiliar artwork','D · Existing import flow, with proposed checks made visible.',nav('wizard','Harbour match strip')+wizard(
`<h2>Bring in your artwork</h2><p>Keep the design. Choose what the operator can change next.</p><div class="drop"><span class="fileicon">SVG</span><strong>harbour-match.svg</strong><p>Illustrator · 1920 × 1080 · 184 KB</p><div class="bottomspace">${btn('Choose another file','small')}</div></div>${box('Import check',`<div class="asset"><span class="green">✓</span>4 text elements <span class="spacer"></span><span class="success">Editable</span></div><div class="asset"><span class="green">✓</span>2 image elements <span class="spacer"></span><span class="success">Embedded</span></div><div class="asset"><span class="green">✓</span>Inter font <span class="spacer"></span><span class="success">Available</span></div>`)}${note('Artwork does not declare score rules or match relationships. You choose those in Fields.')}<div class="finish">${btn('← Back')}${btn('Choose fields →','primary')}</div>`,preview(scoreGraphic(false,'3'),'HARBOUR MATCH STRIP')+box('From the designer','<p>Two team names, two scores and two crests. Decorative shapes remain part of the artwork.</p>'),1),
'Import graphic → Design → choose harbour-match.svg.','The artwork preview appears; Choose fields opens the existing Fields step.','All text, logos and fonts are visible before exposing any operator control.');

add('02-svg-fields','02 / SVG · Expose text, scores and images','D · Uses existing text/image extraction; field review and selection treatment are proposed.',nav('wizard','Harbour match strip')+wizard(
`<h2>Choose what can change</h2><p>Select an element here or on the artwork.</p>${table(['USE','FIELD','TYPE'],[['✓','Home team','Text'],['✓','Away team','Text'],['✓','Home score','Number'],['✓','Away score','Number'],['✓','Home crest','Image'],['✓','Away crest','Image']],2,'compact')}${field('Selected element','Home score <span class="muted">text · “3”</span>')}${field('Field type','Number <span class="muted">▾</span>')}${note('“3” suggests a number. Confirm the type; it does not imply scoring or a Goal action.')}<div class="finish">${btn('← Design')}${btn('Configure controls →','primary')}</div>`,preview(scoreGraphic(true,'3'),'HOME SCORE SELECTED')+box('6 fields exposed','<p>Team labels → Text<br>Score figures → Number<br>Embedded crests → Image</p>')+note('Outlined lettering stays artwork unless you replace it with a positioned text field.','warn')),
'Click Home score on the artwork; confirm Number in the field type selector.','The selected artwork element and its field row highlight together.','Both crests are image fields. No bracket, score rules or actions are inferred from the SVG.');

add('03-svg-controls','03 / SVG · Keep values and actions separate','D · Existing generated controls, with a proposed explicit authoring review.',nav('wizard','Harbour match strip')+wizard(
`<h2>Operator controls</h2><p>Review what changes a value and what operates the graphic.</p>${box('Values',`${field('Home score','Number　·　minimum 0　·　step 1')}${field('Away score','Number　·　minimum 0　·　step 1')}<div class="row">${btn('−')}${btn('+')}<span class="muted" style="font-size:12px">Change the selected score</span></div>`)}${box('Graphic actions',`<div class="listrows">Take / Out <span class="muted">· standard playout actions</span><br>Clear highlight <span class="muted">· explicitly declared</span></div><div class="bottomspace">${btn('+ Add an action…','small')}</div>`)}${note('A new score changes the number. It does not fire Take, Goal, Next or Reset.')}<div class="finish">${btn('← Fields')}${btn('Animation →','primary')}</div>`,preview(scoreGraphic(false,'3'),'CONTROL PREVIEW')+box('Test controls off air',`<div class="row spread"><span>Home score</span><div class="row">${btn('−')}<b>3</b>${btn('+')}</div></div><div class="line"></div><div class="row">${btn('Clear highlight')}<span class="muted" style="font-size:12px">Action</span></div>`)),
'Set Home score to step 1. Test the + control in the off-air preview.','The preview changes from 3 to 4; no animation action is fired.','The field contract and control schema identify values and actions separately.');

add('04-svg-cue','04 / SVG · Finish, add to production, prepare a cue','D · Proposed connection entry point follows the agreed field-led workflow.',prod(scoreGraphic(false,'3'),
box('EDITING PREVIEW CUE · Quarter-final',`<div class="editor-grid">${field('Home team','North <span class="linkbutton">Fill from…</span>')}${field('Away team','Orbit <span class="linkbutton">Fill from…</span>')}${field('Home score','3 <span class="linkbutton">① Connect…</span>')}${field('Away score','2 <span class="linkbutton">Connect…</span>')}</div><div class="grid2"><div class="menu"><div class="active">① Connect…　Google Sheet</div><div>Another system　<span class="muted">data API</span></div><div>Existing production value</div></div><div class="note">Connect follows live values for every cue of this graphic.<br><br>Fill from… copies once into this cue.</div></div>`)),
'Finish → Save & add to Harbour Cup → prepare Quarter-final → Home score → Connect…','Choose Google Sheet, Another system, or an existing production value.','The destination is Home score on this graphic. Creating the cue has not Taken it live.');

add('05-svg-cell','05 / SVG · Connect one score to a Sheet cell','D · Cell/range picker is a new proposal; the shared production binding path is retained.',nav()+`<div class="workspace connect-layout"><div class="stack"><div class="titlebar"><div><div class="breadcrumb">Quarter-final › Home score › Connect</div><h2>Choose a Sheet value</h2><p>Harbour results · tab: Live</p></div>${pill('GOOGLE SHEET','green')}</div>${field('Sheet link','docs.google.com/spreadsheets/d/example… <span>✓</span>')}${table(['','A · name','B · value'],[['1','home_team','North'],['2','away_team','Orbit'],['3','home_score','3'],['4','away_score','2'],['5','home_crest','north.svg'],['6','away_crest','orbit.svg']],2)}${note('Selected B3 → Home score · Number · current value 3','good')}${field('Use value from','Cell B3　<span class="muted">Change selection</span>')}</div><div class="stack">${preview(scoreGraphic(true,'3'),'HOME SCORE = 3','medium')}${box('Connection scope',`<div class="row spread"><b>Harbour match strip</b>${pill('USED BY 2 CUES','amber')}</div><p style="margin-top:12px">Quarter-final and Final follow this score. Choose a separate graphic if they need independent live values.</p>`)}<div class="row spread">${btn('Cancel')}${btn('Connect Home score','primary')}</div></div></div>`,
'In Connect, paste the Sheet link and select cell B3.','The preview highlights Home score and displays the parsed number 3.','The dialog states “Used by 2 cues.” B3 is an explicit cell binding; row movement needs remapping.');

add('06-svg-list','06 / SVG · Add a scrolling list from another tab','D · Demonstrates a column/list without a catalogue template; a scrolling behavior is explicitly authored.',nav()+`<div class="workspace connect-layout"><div class="stack"><div><div class="breadcrumb">Quarter-final › Upcoming matches › Connect</div><h2>Choose a list</h2><p>Harbour schedule · one row per upcoming match</p></div>${field('Source / tab','Harbour schedule　/　Upcoming <span>▾</span>')}${table(['A · time','B · match','C · line'],[['20:30','Lynx vs Reef','Lynx vs Reef at 20:30'],['21:00','Halo vs Kite','Halo vs Kite at 21:00'],['21:30','Volt vs Echo','Volt vs Echo at 21:30']])}${field('Use','Column C · line　<span class="muted">List of text</span>')}${note('3 non-empty lines. The graphic already declares a scrolling list; the source supplies its content.','good')}${box('Content preview','<p>Lynx vs Reef at 20:30<br>Halo vs Kite at 21:00<br>Volt vs Echo at 21:30</p>')}</div><div class="stack">${preview(scoreGraphic(false,'3',true),'SCORES + TEXT + IMAGES + LIST','medium')}${box('Connections on this graphic',`<div class="connections">Home / away score → Harbour results<br>Home / away crest → Harbour results<br>Upcoming matches → Harbour schedule<br>Competition label → Manual</div>`)}<div class="row spread">${btn('Back')}${btn('Connect Upcoming matches','primary')}</div></div></div>`,
'Expose an Upcoming matches list with scrolling behavior, then Connect… → Sheet → Column C.','The list preview uses the selected column in source order.','Text fields, images, scores and a scrolling list coexist. Source layout does not choose a catalogue category.');

add('07-svg-verify','07 / SVG · Verify images and mappings before air','D · Proposed review consolidates the selected fields without changing binding ownership.',nav()+`<div class="workspace connect-layout"><div class="stack"><div><div class="breadcrumb">Harbour match strip › Connections</div><h2>Check the result</h2><p>One graphic · two sources · two cues</p></div>${table(['FIELD','FROM','VALUE'],[['Home team','Live!B1','North'],['Away team','Live!B2','Orbit'],['Home score','Live!B3','3'],['Away score','Live!B4','2'],['Home crest','Live!B5','✓ north.svg'],['Away crest','Live!B6','✓ orbit.svg'],['Upcoming matches','Upcoming!C2:C','3 lines']])}${note('2 images loaded in preview. The output must also be able to load their approved asset references.','good')}${note('Image fallback: keep the last good image on a failed read. Empty SVG image fields restore the original artwork. This is not the same as a failed load.')}</div><div class="stack">${preview(scoreGraphic(false,'3',true),'MAPPED CONTENT','medium')}<div class="metrics"><div class="metric"><strong>7 / 7</strong><span>FIELDS CHECKED</span></div><div class="metric"><strong>2 / 2</strong><span>IMAGES AVAILABLE</span></div><div class="metric"><strong>Off air</strong><span>PREVIEW ONLY</span></div></div><div class="row spread">${btn('Edit connections')}${btn('Save & return to Playout','primary')}</div></div></div>`,
'Check each field against the source sample; inspect both crest images; save the connections.','The cue preview uses the saved live values. Take remains a separate action.','Expected values, image availability and affected cues are visible before any on-air update.');

add('08-svg-live','08 / SVG · Take once, then follow changing values','D · Agreed browser-led reading, source status and manual score behavior.',prod(scoreGraphic(false,'3',true),
box('EDITING ON-AIR CUE · Quarter-final',`<div class="editor-grid">${field('Home score','3 <span class="muted">Connected</span>','Harbour results · Live!B3')}${field('Away score','2 <span class="muted">Connected</span>','Harbour results · Live!B4')}${field('Upcoming matches','3 lines <span class="linkbutton">View connection</span>','Harbour schedule · Upcoming!C2:C')}${field('Competition label','HARBOUR CUP <span class="muted">Manual</span>')}</div><div class="line"></div><div class="row spread"><b>Live numbers</b><div class="row"><span>Home score</span>${btn('−')}${btn('+','primary')}<span class="muted">Shared value</span></div></div>`),{live:true,sources:source('Harbour results','Checked 3 s ago · changed 12 s ago')+source('Harbour schedule','Checked 2 s ago · changed 4 min ago')}),
'Press Take. A Sheet cell edit subsequently updates its connected field without another Take.','The graphic stays on air while values change; controls remain available beside it.','Open-page reads target 5 s. Closed-page published reads use about a minute; real latency still needs qualification.');

add('09-bracket-author','09 / Bracket · Declare matches, not just sixteen labels','A · Structured authoring is a new proposal, layered over ordinary fields and declared actions.',nav('wizard','Harbour Top 16')+`<div class="workspace split-wide"><div class="stack">${preview(bracket(),'TOP 16 · 8 OPENING MATCHES','large')}${box('Authoring intent',`<p>Codex creates the artwork plus named team, score and crest slots. It must validate 16 unique teams, 15 matches, valid progression references and no cyclic match relationships.</p>`)}${note('Artwork can suggest repeated groups. The author confirms match IDs and relationships; the importer cannot infer a tournament.')}</div><div class="stack"><h2>Graphic contract</h2>${box('Repeated structure',`<div class="listrows">Teams　16<br>Matches　15<br>Key　match_id<br>Relationship　next_match + next_slot</div>`)}${box('Each match exposes',`<div class="badge-line">${pill('Home team')}${pill('Away team')}${pill('Home crest')}${pill('Away crest')}${pill('Home score')}${pill('Away score')}</div>`)}${box('Operator actions',`<p>Highlight winner<br>Advance selected winner<br>Reset selection</p>`)}${note('Confirm these groups before connecting rows. Each match keeps its own team, crest and score fields.','warn')}${btn('Validate & add to production','primary')}</div></div>`,
'Create/import the bracket, then confirm the declared match structure and actions.','Validation reports missing IDs, invalid relationships or duplicate match slots before the graphic is saved.','All 16 teams are visible. A score value alone does not advance the bracket.');

add('10-bracket-connect','10 / Bracket · Match structured rows by stable IDs','A · New mapping proposal: explicit row keys plus a finite field map, without formulas.',nav()+`<div class="workspace connect-layout tight"><div class="stack"><div><div class="breadcrumb">Top 16 overview › Matches › Connect</div><h2>Connect the match set</h2><p>Harbour bracket · Matches tab</p></div>${table(['match_id','home','away','home_score','away_score'],[['R16-01','North','Orbit','3','2'],['R16-02','Lynx','Reef','0','0'],['R16-03','Halo','Kite','0','0'],['R16-04','Volt','Echo','0','0']],0)}${field('Match rows to slots using','match_id　→　Graphic match ID')}${map('home_score','Home score')}${map('away_score','Away score')}${map('home_crest / away_crest','Home crest / Away crest')}${note('Row order can change. R16-01 still targets the same match. Missing or duplicate IDs block this mapping.','good')}${btn('Validate 15 match rows','primary')}</div><div class="stack">${preview(bracket(),'SOURCE → MATCH R16-01','medium')}${box('Relationship review',`${table(['MATCH','NEXT MATCH','SLOT'],[['R16-01','QF-01','Home'],['R16-02','QF-01','Away']],-1,'compact')}<p style="margin-top:12px">Relationships describe the authored bracket. Progression is applied only by the declared operator action.</p>`)}<div class="row spread">${pill('NEW PROPOSAL','amber')}${btn('Connect Matches','primary')}</div></div></div>`,
'Select match_id as the row key, map columns to match fields, then validate the full set.','A mapping preview resolves source rows to bracket slots independently of row order.','The existing engine does not bind object arrays directly. This screen proposes an adapter to existing leaf bindings.');

add('11-bracket-live','11 / Bracket · Scores update; the operator advances','A · Proposed bracket controls preserve the rule that data does not operate the show.',prod(bracket(),
box('MATCH R16-01 · North vs Orbit',`<div class="grid3">${field('Home score','3 <span class="muted">Sheet</span>')}${field('Away score','2 <span class="muted">Sheet</span>')}${field('Selected winner','North <span>▾</span>')}</div><div class="row spread"><div><b>Advance North → QF-01 · Home</b><p style="font-size:12px;margin-top:5px">Apply only after confirming the match result.</p></div>${btn('① Advance selected winner','primary')}</div><div class="line"></div><div class="row">${btn('Highlight winner')}${btn('Clear highlight')}${btn('Reset…','ghost')}</div>`),{kind:'bracket',live:true,sources:source('Harbour bracket','Checked 2 s ago · 15 matches')}),
'Select R16-01, confirm North as winner, then press Advance selected winner.','The declared action updates the downstream bracket slot; a subsequent score edit cannot fire it.','Upstream result changes after advancement need an explicit correction flow. Its details remain a design decision.');

add('12-provider-import','12 / Commercial roll · Package and hosted content are different','B · Proposed provider intake distinguishes editable local material from a remote render.',nav('wizard','North partner roll')+`<div class="workspace connect-layout"><div class="stack"><h2>Bring in provider graphics</h2><p>Choose the material the provider supplied.</p><div class="choice active"><span class="call">1</span><div><h3>Import assets or a compatible package</h3><p>SVG, images and media; or a package with a supported graphic contract. Inspect assets, fonts and declared fields.</p><div class="bottomspace">${btn('Choose files…','primary small')}</div></div></div><div class="choice"><span class="call">2</span><div><h3>Reference hosted content</h3><p>Use the provider’s render URL. It stays remote and needs a reachable, embeddable page. Editable fields require a supported provider contract.</p><div class="bottomspace">${btn('Enter hosted URL…','small')}</div></div></div>${note('An arbitrary ZIP or web page does not become an editable NoaCG graphic. Unsupported material needs conversion or a defined adapter.','warn')}</div><div class="stack">${preview(ad(),'PROVIDER ARTWORK','large')}${box('Campaign fixture','<p>North Equipment · three-slide partner roll<br>Headline, product image, sponsor logo and legal line<br>Advance and Reset are operator actions.</p>')}</div></div>`,
'Choose Import assets for supplied files, or Reference hosted content for a provider URL.','Each route gets its own readiness checks and capability preview.','Packaging assets transfers material. A hosted URL keeps rendering and availability under the provider’s control.');

add('13-provider-package','13 / Commercial roll · Inspect a supplied package','B · Proposed package inspection; the example assumes a compatible manifest.',nav('wizard','North partner roll')+`<div class="workspace connect-layout"><div class="stack"><div class="titlebar"><div><h2>North campaign package</h2><p>north-partner-roll.zip · compatible manifest detected</p></div>${pill('3 SLIDES')}</div>${box('Assets',`<div class="asset"><span class="thumb">N</span><div>north-logo.svg<br><small class="muted">Sponsor logo</small></div><span class="spacer"></span><span class="success">Ready</span></div><div class="asset"><span class="thumb">▥</span><div>bottle-product.webp<br><small class="muted">Product image</small></div><span class="spacer"></span><span class="success">Ready</span></div><div class="asset"><span class="thumb">Aa</span><div>Inter<br><small class="muted">Typeface</small></div><span class="spacer"></span><span class="success">Available</span></div>`)}${table(['DECLARED FIELD','TYPE','SAMPLE'],[['Headline','Text','Built for the long run.'],['Product image','Image','bottle-product.webp'],['Legal line','Text','Official hydration partner']])}${note('Imported assets can be packaged with the graphic. Later provider changes are not automatically included.')}<div class="row spread">${btn('Back')}${btn('Expose fields & continue','primary')}</div></div><div class="stack">${preview(ad(),'SLIDE 1 OF 3','large')}${box('Declared actions',`<div class="controlrow">${btn('Next slide')}${btn('Reset roll')}</div><p style="margin-top:12px">Data can replace content. It cannot press these buttons.</p>`)}</div></div>`,
'Choose the ZIP, inspect its declared fields and asset checks, then continue.','The local graphic exposes editable content and preserves the provider’s artwork.','An unsupported manifest or missing required asset blocks readiness with the exact conversion/replacement needed.');

add('14-provider-hosted','14 / Commercial roll · A URL does not imply editable fields','B · Hosted-content UI is a new proposal. Capabilities remain explicit and provider-dependent.',nav('wizard','Hosted partner bumper')+`<div class="workspace connect-layout"><div class="stack"><h2>Reference hosted content</h2>${field('Provider render URL','https://graphics.example/harbour/north')}<div class="row">${btn('Check availability','primary')}${pill('SIMULATED RESULT','amber')}</div>${table(['CHECK','RESULT'],[['HTTPS & reachability','Passed in this sample'],['Embedding permission','Allowed in this sample'],['Editable-field contract','Not supplied'],['Asset dependencies','Provider-hosted']])}${note('This page exposes no compatible fields. Show it as supplied, or ask the provider for an editable package/contract.','warn')}${box('Available controls',`<p>NoaCG: Take / Out wrapper<br>Next / Reset: unavailable without a supported provider control contract</p>`)}${btn('Add as hosted graphic','primary')}</div><div class="stack">${preview(ad(),'REMOTE RENDER · NO FIELD ACCESS','large')}${box('Availability',`<p>Internet access and provider uptime are required. Preview is not a portability guarantee. Recheck the actual output environment before use.</p>`)}${note('No arbitrary API URL mapper or cross-origin DOM editing is implied by this proposal.')}</div></div>`,
'Enter the hosted URL and inspect reachability, embedding and contract results.','NoaCG shows a remote preview with only the controls the integration can actually support.','No field mapping is offered when the provider has not declared editable content.');

add('15-provider-live','15 / Commercial roll · External content, deliberate playback','B · Imported-package route: data supplies content; the operator controls the roll.',prod(ad(),
box('NORTH PARTNER ROLL · Slide 1 of 3',`<div class="editor-grid">${field('Headline','Built for the long run.','Connected · North campaign API')}${field('Product image','bottle-product.webp　✓','Connected · approved asset reference')}${field('Legal line','Official hydration partner','Connected · North campaign API')}${field('Campaign label','HARBOUR CUP','Manual')}</div><div class="line"></div><div class="row spread"><div class="row">${btn('① Next slide','primary')}${btn('Reset roll')}</div><span class="muted" style="font-size:12px">Operator actions</span></div>`),{kind:'ad',live:true,sources:source('North campaign API','Received 8 s ago','Details')}),
'Preview the supplied content, Take the roll, then press Next slide for each planned advance.','API values update declared fields; playback advances only when the operator asks.','If provider-hosted media becomes unavailable, switch to a separately prepared local fallback cue.');

add('16-player-author','16 / Player overlay · Author the mixed-content contract','C · Text, image, score, status and scrolling list in one graphic, with separate actions.',nav('wizard','Ari player overlay')+`<div class="workspace split-wide"><div class="stack">${preview(player(),'ABOVE PLAYER VIDEO','large')}${box('Create with Codex or configure visually',`<p>Both routes produce the same declared fields and controls. Validation checks field IDs, compatible types, sample content and action separation before the graphic is added to the production.</p>`)}${note('Video is illustrative. The overlay is the name card, score, status and scrolling strip.')}</div><div class="stack"><h2>Editable content</h2>${table(['FIELD','TYPE'],[['Player name','Text'],['Portrait','Image'],['Score','Number'],['Status','Choice value'],['Recent updates','List of text']])}${box('Actions',`<div class="listrows">Take / Out<br>Flash player<br>Clear emphasis</div>`)}${note('“Ready” is a data value. “Flash player” is an action. A status update cannot trigger the action.','good')}${btn('Save & add to production','primary')}</div></div>`,
'Create the overlay and confirm its fields and actions in the authoring review.','The graphic enters the library with explicit, source-independent editable content.','The same declaration supports manual values, Sheet content and API values together.');

add('17-player-api','17 / Player overlay · Connect an API value or collection','C · Uses the existing push API; arbitrary JSON-address fetching remains outside the agreed run.',nav('production','Harbour Cup',true)+`<div class="workspace connect-layout"><div class="stack"><div><div class="breadcrumb">Ari overlay › Score › Connect › Another system</div><h2>Choose received data</h2><p>Production is published · data key hidden</p></div>${box('Send to this production',`<div class="fake-url">PATCH https://noacg.studio/api/data/patch</div><div class="row bottomspace">${btn('Copy example','small')}${btn('Reveal data key','small ghost')}</div>`)}<div class="code">{ "player": {\n    "name": "Ari Kova",\n    "score": 12,\n    "status": "Ready",\n    "updates": ["Last round +3", "Best streak 7"]\n  } }</div>${table(['RECEIVED VALUE','CURRENT','CONNECT TO'],[['Player · score','12','Score'],['Player · status','Ready','Status'],['Player · updates','2 text items','Recent updates']],0)}${note('Text collections can fill a list. Collections of objects need explicit item mapping; they are not a direct binding.')}<div class="row spread">${pill('RECEIVED 2 S AGO','green')}${btn('Connect selected values','primary')}</div></div><div class="stack">${preview(player(),'API SAMPLE → OVERLAY','large')}${box('Credentials stay with the sender','<p>Give the production data key to the authorized sender. Nothing in this screen gives the output renderer a writer credential.</p>')}</div></div>`,
'Publish, provide the sender its data key, then select the received Score, Status and Updates values.','The field picker previews real data names and values rather than requiring typed paths.','This is pushed API data, not a claim that arbitrary external JSON URLs are already supported.');

add('18-player-row','18 / Player overlay · Fill a selected roster row once','C · Existing row-to-cue behavior, with a proposed explicit field mapping review.',nav()+`<div class="workspace connect-layout"><div class="stack"><div><div class="breadcrumb">Ari overlay › Player details › Fill from…</div><h2>Choose a player</h2><p>Harbour roster · source: Google Sheet</p></div>${table(['player_id','name','portrait','team'],[['P07','Ari Kova','ari.webp','North'],['P12','Mika Vale','mika.webp','Orbit'],['P19','Lea Marin','lea.webp','Lynx']],0)}${map('name','Player name')}${map('portrait','Portrait')}${map('team','Team label')}${note('Fill copies this row into the cue. Roster edits will not change this prepared player card.','good')}${note('Score and Recent updates stay connected to their own sources. Unmapped fields keep their values.')}<div class="row spread">${btn('Cancel')}${btn('Fill this cue','primary')}</div></div><div class="stack">${preview(player(),'ROSTER ROW P07','large')}${box('One graphic, mixed ownership',`<div class="connections">Player name + portrait → this cue, from roster P07<br>Score + status → connected API values<br>Recent updates → connected list<br>Flash player → operator action</div>`)}</div></div>`,
'Fill from… → roster → select P07 → confirm the name, portrait and team mapping.','Those three fields are copied into this cue; existing API connections stay intact.','Fill is a snapshot. Live selection by row key would be a distinct proposed Connect behavior, not implied here.');

add('19-player-live','19 / Player overlay · Operate without losing value ownership','C · Demonstrates multiple sources on one graphic and intentional sharing across graphics.',prod(player('12'),
box('EDITING ON-AIR CUE · Ari overlay',`<div class="editor-grid">${field('Player name','Ari Kova','This cue · filled from roster P07')}${field('Score','12 <span class="linkbutton">View connection</span>','Match API · also used by North scorebug')}${field('Status','Ready','Match API · current value')}${field('Recent updates','2 lines','Harbour activity · connected Sheet list')}</div><div class="line"></div><div class="row spread"><div class="row"><b>Score</b>${btn('−')}${btn('+','primary')}</div><div class="row">${btn('Flash player')}${btn('Clear emphasis')}</div></div><p style="font-size:12px;margin-top:12px">A score press changes the shared value. The next API push can replace it.</p>`),{kind:'player',live:true,sources:source('Match API','Received 2 s ago','Details')+source('Harbour activity','Checked 3 s ago')}),
'Take Ari’s cue. Use + for a manual correction or Flash player for the explicit visual action.','A score correction also updates the North scorebug because both intentionally share the value.','Sheet overrides last until the source cell changes; pushed API updates can overwrite on the next write.');

add('20-recovery-failed','20 / Recovery · Failed reads keep the last good values','D + C · Agreed stale behavior; source and field warnings stay visible in Playout.',prod(scoreGraphic(false,'3',true),
box('HARBOUR RESULTS · Cannot read since 20:14:05',`<div class="grid2"><div>${field('Home score','3 <span class="pill red">STALE</span>','Last good value · 20:14:00')}${field('Away score','2 <span class="pill red">STALE</span>','Last good value · 20:14:00')}</div><div>${note('The Sheet is no longer shared. Restore link access to the required tab, then check again.','warn')}<div class="controlrow">${btn('Open source')}${btn('① Check again','primary')}${btn('Pause')}</div></div></div><div class="line"></div><p>Program keeps 3 : 2 and the last good images. The independent schedule source continues updating.</p>`),{live:true,sources:source('Harbour results','Can’t read · not shared · stale','Pause',true)+source('Harbour schedule','Checked 2 s ago')}),
'Restore sharing in the Sheet, return to Playout and press Check again.','A successful read clears the stale marker and applies changed cells. Failed reads write nothing.','An unavailable source never becomes an empty score or an automatic Out action.');

add('21-recovery-override','21 / Recovery · Pause holds an operator’s correction','D · D4 retained: shared manual value, changed-cell comparison, no Sheet writeback.',prod(scoreGraphic(false,'4',true),
box('HOME SCORE · Manual value while paused',`<div class="metrics"><div class="metric"><strong>4</strong><span>SHARED VALUE / ON AIR</span></div><div class="metric"><strong>3</strong><span>LAST GOOD SHEET VALUE</span></div><div class="metric"><strong>2</strong><span>GRAPHICS USING THIS SCORE</span></div></div><div class="line"></div><div class="row spread"><div><b>Harbour results is paused</b><p style="font-size:12px;margin-top:8px">The + press updated both graphics. Nothing was written back to the Sheet.</p></div>${btn('① Resume','primary')}</div><div class="bottomspace">${note('On Resume, only cells changed since the last good source snapshot replace their values. If B3 is still 3, the manual 4 stays.','good')}</div>`),{live:true,sources:source('Harbour results','Paused · manual correction active','Resume')+source('Harbour schedule','Checked 3 s ago')}),
'Pause Harbour results, then press Home score +. Resume when ready.','The correction changes the shared value on both graphics; unchanged source cells do not erase it.','If B3 changes to 5 during Pause, Resume applies 5. API Pause is a later, separately qualified capability.');

add('22-recovery-empty','22 / Recovery · A valid empty list is not a failed read','D + C · Agreed adapters clear on valid empty reads; failures preserve the previous content.',nav('production','Harbour Cup',true)+`<div class="workspace connect-layout"><div class="stack"><h2>Harbour activity recovered</h2>${source('Harbour activity','Checked just now · empty')}${table(['A · item','B · time'],[['—','No rows']])}${note('The source read succeeded. This list contains zero items.','good')}${box('What changes',`<p>The scrolling strip clears. Player name, portrait, status and score remain because they come from other values or sources.</p>`)}${box('What would happen on failure',`<p>A failed read would keep the last good list and display a stale/error state. It would not clear the strip.</p>`)}${btn('Return to Playout','primary')}</div><div class="stack">${preview(player().replace(/<div class="scroll">.*?<\/div>/,''),'LIST CLEARED · OTHER FIELDS REMAIN','large')}${note('The adapter emits an empty string for this valid empty list. Legacy null / object / missing-path semantics remain unchanged.')}</div></div>`,
'After source access is restored, inspect the successful read and zero-item result.','The empty list clears the strip through an ordinary data update; the graphic remains on air.','“Empty” is shown only after a valid read. It is never a fallback interpretation of a network failure.');

add('23-disconnect-reuse','23 / Reuse · Disconnect deliberately, then reconnect elsewhere','All scenarios · Proposed reuse review preserves contracts while treating production sources separately.',nav('production','Harbour Cup',true)+`<div class="workspace connect-layout"><div class="stack"><div class="breadcrumb">Harbour match strip › Upcoming matches</div><h2>Disconnect this field?</h2>${box('Current connection',`<div class="listrows">Harbour schedule → Upcoming matches<br>Graphic: Harbour match strip<br>Used by 2 cues</div>`)}${note('Both cues return to cue-owned content using the last value. Other fields and other graphics connected to this source are unaffected.','warn')}${box('Last value to keep',`<p>Lynx vs Reef at 20:30<br>Halo vs Kite at 21:00<br>Volt vs Echo at 21:30</p>`)}<div class="row spread">${btn('Keep connection')}${btn('Disconnect Upcoming matches','primary')}</div><div class="line"></div><p style="font-size:13px">Published connection changes are intended to save immediately under C2. Today’s implementation still requires republishing bindings.</p></div><div class="stack"><div class="breadcrumb">New production › Coastal Open › Add graphic</div><h2>Reuse the graphic</h2>${canvas(scoreGraphic(false,'0'),'medium')}${box('Connection review',`${map('Harbour results','Choose Coastal results…')}${map('Harbour schedule','Choose Coastal schedule…')}<p style="margin-top:12px">Keep fields, artwork and controls. Reconfirm production sources and row keys. Do not copy data keys.</p>`)}<div class="row spread">${pill('NEW PROPOSAL','amber')}${btn('Review & add','primary')}</div></div></div>`,
'Disconnect the selected field; when reusing the graphic, review every production-specific source.','The old production retains its own sources. The new one gets explicitly chosen connections and credentials.','Schema changes or missing field IDs require remapping. No existing plan or authority is changed by these screens.');

await fs.writeFile(new URL('mockups.html',import.meta.url),`<!doctype html><html lang="en"><head><meta charset="utf-8"><title>NoaCG custom graphics — static research mockups</title><style>${css}</style></head><body>${slides.map(s=>s.html).join('\n')}</body></html>`);
console.log(`Generated ${slides.length} static screens.`);
